'use strict';
/* TableGate World Studio + Virtual Tabletop
   Local-first campaign authoring and play tools that sit beside the connected
   messenger/organizer backend. Shared sync is attempted when the backend exposes
   getTablegateStudio/saveTablegateStudio; otherwise data remains portable in the
   browser and through campaign package export/import. */

const StudioData={
  loadedFor:'',backendSupported:null,saveTimer:null,lastSyncedAt:'',
  data:null,
  templates:[
    {id:'location',name:'Location',icon:'⌖',fields:['Geography','Climate','History','People','Sites','Secrets']},
    {id:'settlement',name:'Settlement',icon:'🏰',fields:['Government','Districts','Population','Economy','Defenses','Factions']},
    {id:'character',name:'Character',icon:'♟',fields:['Appearance','Personality','History','Goals','Relationships','Secrets']},
    {id:'organization',name:'Organization',icon:'⚜',fields:['Purpose','Structure','Resources','Members','Allies','Rivals']},
    {id:'species',name:'Species or Ancestry',icon:'𓆣',fields:['Physiology','Culture','Homelands','Languages','Traits','History']},
    {id:'item',name:'Item or Artifact',icon:'⚔',fields:['Appearance','Properties','History','Owners','Powers','Complications']},
    {id:'deity',name:'Deity or Faith',icon:'✦',fields:['Domains','Doctrine','Worship','Clergy','Holy Sites','Myths']},
    {id:'event',name:'Historical Event',icon:'⌛',fields:['Date','Causes','Participants','Course','Outcome','Legacy']},
    {id:'adventure',name:'Adventure',icon:'🗝',fields:['Premise','Hooks','Scenes','NPCs','Locations','Rewards']},
    {id:'rules',name:'House Rule',icon:'⚖',fields:['Purpose','Rule Text','Examples','Exceptions','Rulings','Revision Notes']}
  ],
  defaults(){
    const now=new Date().toISOString(),articleId=uid(),sceneId=uid(),mapId=uid(),characterId=uid();
    return {version:1,updatedAt:now,world:{name:'Untitled World',subtitle:'A living campaign setting',summary:'Build the setting, connect its people and places, then bring it directly to the table.',activeTab:'overview',selectedArticleId:articleId,selectedMapId:mapId,search:'',categoryFilter:'all',articles:[{id:articleId,title:'Welcome to the World',template:'location',category:'World Overview',status:'draft',visibility:'party',tags:['start here'],excerpt:'This starter article demonstrates the linked campaign encyclopedia.',content:'# Welcome\n\nUse articles to document places, characters, factions, cultures, adventures, rules, and anything else that belongs in your campaign.\n\nLink articles by writing `[[Article Name]]` in the body.',createdAt:now,updatedAt:now}],categories:[{id:uid(),name:'World Overview',parentId:'',icon:'🌐'},{id:uid(),name:'People',parentId:'',icon:'♟'},{id:uid(),name:'Places',parentId:'',icon:'⌖'},{id:uid(),name:'Organizations',parentId:'',icon:'⚜'},{id:uid(),name:'Lore & History',parentId:'',icon:'⌛'}],maps:[{id:mapId,name:'Campaign Atlas',imageDataUrl:'',width:1600,height:1000,pins:[],notes:'Upload a regional, city, dungeon, or galaxy map and place linked pins.',createdAt:now}],timelineEvents:[],relations:[]},vtt:{activeTab:'table',activeSceneId:sceneId,tool:'select',gridEnabled:true,gridSize:70,snap:true,zoom:1,panX:0,panY:0,selectedTokenId:'',scenes:[{id:sceneId,name:'First Scene',width:1600,height:1000,backgroundDataUrl:'',backgroundName:'',gridSize:70,gridEnabled:true,gridColor:'rgba(255,255,255,.22)',tokens:[],drawings:[],fog:[],notes:'',createdAt:now}],characters:[{id:characterId,name:'Sample Hero',player:'',system:'System Neutral',portraitDataUrl:'',tokenDataUrl:'',color:'#d4aa57',hp:10,maxHp:10,ac:10,speed:'30 ft',initiativeBonus:0,stats:{Strength:10,Dexterity:10,Constitution:10,Intelligence:10,Wisdom:10,Charisma:10},notes:'Use the character editor for a compact universal sheet, then store complete system data as JSON.',sheetJson:{},createdAt:now,updatedAt:now}],handouts:[],initiative:[],round:1,turnIndex:0,diceLog:[],chatLog:[]},settings:{autosave:true,backendSync:true,showGridLabels:false}};
  },
  key(){return `${CONFIG.storagePrefix}.studio.${State.server?.id||'local'}`},
  async load(force=false){
    const serverId=State.server?.id||'local';if(!force&&this.data&&this.loadedFor===serverId)return this.data;
    const local=Store.get(`studio.${serverId}`,null);this.data=this.normalize(local||this.defaults());this.loadedFor=serverId;
    if(State.token&&State.server&&this.data.settings.backendSync!==false){
      try{const remote=await API.call('getTablegateStudio',{serverId},true);if(remote?.studio){this.data=this.normalize(remote.studio);Store.set(`studio.${serverId}`,this.data);this.backendSupported=true;this.lastSyncedAt=remote.updatedAt||new Date().toISOString()}}
      catch(err){if(['UNKNOWN_ACTION','NOT_FOUND','API_ERROR'].includes(err?.code)||/unknown|unsupported|action/i.test(err?.message||''))this.backendSupported=false;else console.warn('Studio sync load failed; using local copy.',err)}
    }
    return this.data;
  },
  normalize(raw){const base=this.defaults(),d=raw&&typeof raw==='object'?raw:{};return {...base,...d,world:{...base.world,...(d.world||{})},vtt:{...base.vtt,...(d.vtt||{})},settings:{...base.settings,...(d.settings||{})}}},
  save(immediate=false){if(!this.data)return;this.data.updatedAt=new Date().toISOString();Store.set(`studio.${this.loadedFor||State.server?.id||'local'}`,this.data);clearTimeout(this.saveTimer);if(immediate)this.sync();else this.saveTimer=setTimeout(()=>this.sync(),1700)},
  async sync(){
    if(!this.data||!State.token||!State.server||this.data.settings.backendSync===false||this.backendSupported===false)return;
    const payload=JSON.stringify(this.data);if(payload.length>4_000_000){this.backendSupported=false;toast('Studio saved locally. Its embedded media is too large for backend sync; export a campaign package for backup.','info',6500);return}
    try{const res=await API.call('saveTablegateStudio',{serverId:State.server.id,studio:this.data},true);this.backendSupported=true;this.lastSyncedAt=res?.updatedAt||new Date().toISOString()}
    catch(err){if(['UNKNOWN_ACTION','NOT_FOUND','API_ERROR'].includes(err?.code)||/unknown|unsupported|action/i.test(err?.message||''))this.backendSupported=false;else console.warn('Studio sync save failed; local copy is safe.',err)}
  },
  world(){return this.data.world},vtt(){return this.data.vtt},scene(){return this.vtt().scenes.find(s=>s.id===this.vtt().activeSceneId)||this.vtt().scenes[0]},
  article(id){return this.world().articles.find(a=>a.id===id)},character(id){return this.vtt().characters.find(c=>c.id===id)},
  articleLinks(text){const names=[...String(text||'').matchAll(/\[\[([^\]]+)\]\]/g)].map(m=>m[1].trim());return names.map(name=>this.world().articles.find(a=>a.title.toLowerCase()===name.toLowerCase())).filter(Boolean)},
  markdown(text){
    let s=esc(text||'');s=s.replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h1>$1</h1>');
    s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>');
    s=s.replace(/\[\[([^\]]+)\]\]/g,(_,name)=>{const a=this.world().articles.find(x=>x.title.toLowerCase()===name.trim().toLowerCase());return a?`<button class="wiki-link" data-open-article="${esc(a.id)}">${esc(name)}</button>`:`<span class="broken-wiki-link">${esc(name)}</span>`});
    s=s.replace(/^[-*] (.+)$/gm,'<li>$1</li>').replace(/(?:<li>.*<\/li>\n?)+/g,m=>`<ul>${m}</ul>`).replace(/\n{2,}/g,'</p><p>').replace(/\n/g,'<br>');return `<p>${s}</p>`;
  },
  download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1200)},
  fileToDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Could not read file'));r.readAsDataURL(file)})}
};

const WorldStudio={
  async ensure(){await StudioData.load()},
  render(){const w=StudioData.world();return `<div class="studio-shell world-studio"><div class="studio-subnav">${[['overview','Overview'],['articles','Articles'],['atlas','Atlas'],['timeline','Timeline'],['relations','Relationships'],['templates','Templates'],['portable','Import / Export']].map(([id,label])=>`<button data-world-tab="${id}" class="${w.activeTab===id?'active':''}">${label}</button>`).join('')}</div><div id="world-studio-content">${this.renderTab(w.activeTab)}</div></div>`},
  renderTab(tab){if(tab==='articles')return this.articles();if(tab==='atlas')return this.atlas();if(tab==='timeline')return this.timeline();if(tab==='relations')return this.relations();if(tab==='templates')return this.templates();if(tab==='portable')return this.portable();return this.overview()},
  overview(){const w=StudioData.world(),published=w.articles.filter(a=>a.status==='published').length,links=w.articles.reduce((n,a)=>n+StudioData.articleLinks(a.content).length,0),recent=[...w.articles].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,6);return `<div class="workspace-grid"><section class="workspace-card span-12 world-hero"><div><span class="eyebrow">CAMPAIGN WORLD</span><h2>${esc(w.name)}</h2><p>${esc(w.subtitle)}</p></div><button class="primary" data-edit-world-profile>Edit world profile</button></section>${[['📜',w.articles.length,'Articles'],['✓',published,'Published'],['⌖',w.maps.length,'Maps'],['⇄',links,'Article links']].map(([i,n,l])=>`<section class="workspace-card span-3"><div class="metric"><div class="metric-icon">${i}</div><div><strong>${n}</strong><small>${l}</small></div></div></section>`).join('')}<section class="workspace-card span-8"><div class="card-head"><h2>Recently edited</h2><button data-new-article>＋ Article</button></div><div class="document-list">${recent.map(a=>this.articleRow(a)).join('')||'<div class="empty-workspace">No articles yet.</div>'}</div></section><section class="workspace-card span-4"><div class="card-head"><h2>World summary</h2></div><p class="long-copy">${esc(w.summary)}</p><div class="workspace-actions"><button data-world-tab="atlas">Open atlas</button><button data-world-tab="timeline">Open timeline</button></div></section><section class="workspace-card span-6"><div class="card-head"><h2>Fast creation</h2></div><div class="template-grid compact">${StudioData.templates.slice(0,6).map(t=>`<button class="template-card" data-new-from-template="${t.id}"><span>${t.icon}</span><b>${esc(t.name)}</b></button>`).join('')}</div></section><section class="workspace-card span-6"><div class="card-head"><h2>Campaign portability</h2></div><p class="long-copy">The world encyclopedia and virtual tabletop share one campaign package. Export it before changing devices or embedding large map/token images.</p><div class="workspace-actions"><button data-export-studio>Export package</button><button data-world-tab="portable">Import tools</button></div></section></div>`},
  articleRow(a){return `<article class="document-row clickable" data-open-article="${esc(a.id)}"><div class="document-icon">${StudioData.templates.find(t=>t.id===a.template)?.icon||'📜'}</div><div><h4>${esc(a.title||'Untitled')}</h4><p>${esc(a.category||'Uncategorized')} · ${esc(a.status||'draft')} · ${esc((a.tags||[]).join(', '))}</p></div><span class="status-pill ${a.status==='published'?'approved':'pending'}">${esc(a.visibility||'party')}</span></article>`},
  articles(){const w=StudioData.world(),q=String(w.search||'').toLowerCase(),items=w.articles.filter(a=>(w.categoryFilter==='all'||a.category===w.categoryFilter)&&(!q||[a.title,a.excerpt,a.content,(a.tags||[]).join(' ')].join(' ').toLowerCase().includes(q))).sort((a,b)=>a.title.localeCompare(b.title)),selected=StudioData.article(w.selectedArticleId)||items[0];return `<div class="wiki-layout"><aside class="wiki-browser workspace-card"><div class="card-head"><h2>Encyclopedia</h2><button class="primary" data-new-article>＋</button></div><input class="studio-search" id="world-article-search" value="${esc(w.search)}" placeholder="Search the world…"><select id="world-category-filter"><option value="all">All categories</option>${w.categories.map(c=>`<option ${w.categoryFilter===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="wiki-list">${items.map(a=>`<button data-open-article="${a.id}" class="${selected?.id===a.id?'active':''}"><span>${StudioData.templates.find(t=>t.id===a.template)?.icon||'📜'}</span><span><b>${esc(a.title)}</b><small>${esc(a.category||'Uncategorized')}</small></span></button>`).join('')||'<div class="empty-workspace">No matching articles.</div>'}</div><button class="secondary wide" data-manage-categories>Manage categories</button></aside><section class="workspace-card wiki-editor">${selected?this.articleEditor(selected):'<div class="empty-workspace">Create or select an article.</div>'}</section></div>`},
  articleEditor(a){const links=StudioData.articleLinks(a.content),backlinks=StudioData.world().articles.filter(x=>StudioData.articleLinks(x.content).some(y=>y.id===a.id));return `<div class="article-toolbar"><div><span class="eyebrow">${esc(a.category||'UNCATEGORIZED')}</span><h2>${esc(a.title)}</h2></div><div class="workspace-actions"><button data-preview-article="${a.id}">Preview</button><button class="danger" data-delete-article="${a.id}">Delete</button><button class="primary" data-save-article="${a.id}">Save</button></div></div><div class="article-form"><div class="split"><div class="field"><label>Title</label><input id="article-title" value="${esc(a.title)}"></div><div class="field"><label>Template</label><select id="article-template">${StudioData.templates.map(t=>`<option value="${t.id}" ${a.template===t.id?'selected':''}>${t.icon} ${esc(t.name)}</option>`).join('')}</select></div></div><div class="split"><div class="field"><label>Category</label><select id="article-category">${StudioData.world().categories.map(c=>`<option ${a.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}<option ${a.category==='Uncategorized'?'selected':''}>Uncategorized</option></select></div><div class="field"><label>Tags</label><input id="article-tags" value="${esc((a.tags||[]).join(', '))}" placeholder="kingdom, npc, secret"></div></div><div class="split"><div class="field"><label>Status</label><select id="article-status">${['draft','review','published','archived'].map(x=>`<option ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Visibility</label><select id="article-visibility">${['private','runner','party','public'].map(x=>`<option ${a.visibility===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Summary</label><textarea id="article-excerpt" rows="2">${esc(a.excerpt||'')}</textarea></div><div class="field"><label>Article body (Markdown + [[Article Links]])</label><textarea id="article-content" class="article-body" rows="20">${esc(a.content||'')}</textarea></div><div class="relationship-strip"><div><b>Outgoing links</b><p>${links.map(x=>`<button class="wiki-link" data-open-article="${x.id}">${esc(x.title)}</button>`).join(' ')||'None yet'}</p></div><div><b>Backlinks</b><p>${backlinks.map(x=>`<button class="wiki-link" data-open-article="${x.id}">${esc(x.title)}</button>`).join(' ')||'None yet'}</p></div></div></div>`},
  atlas(){const w=StudioData.world(),map=w.maps.find(m=>m.id===w.selectedMapId)||w.maps[0];return `<div class="atlas-layout"><aside class="workspace-card atlas-list"><div class="card-head"><h2>Maps</h2><button class="primary" data-new-map>＋</button></div>${w.maps.map(m=>`<button data-select-map="${m.id}" class="atlas-card ${map?.id===m.id?'active':''}"><span class="atlas-thumb" style="${m.imageDataUrl?`background-image:url('${m.imageDataUrl}')`:''}">⌖</span><span><b>${esc(m.name)}</b><small>${m.pins?.length||0} pins</small></span></button>`).join('')}</aside><section class="workspace-card atlas-main">${map?`<div class="card-head"><div><span class="eyebrow">INTERACTIVE ATLAS</span><h2>${esc(map.name)}</h2></div><div class="workspace-actions"><label class="file-button">Upload map<input type="file" id="atlas-image-input" accept="image/*"></label><button data-toggle-pin-mode class="${w.pinMode?'primary':''}">${w.pinMode?'Click map to place pin':'Place pin'}</button><button data-edit-map="${map.id}">Settings</button></div></div><div class="atlas-canvas ${w.pinMode?'pin-mode':''}" data-atlas-map="${map.id}" style="aspect-ratio:${map.width||1600}/${map.height||1000};${map.imageDataUrl?`background-image:url('${map.imageDataUrl}')`:''}">${map.imageDataUrl?'':'<div class="map-empty"><span>🗺</span><b>Upload a map image</b><small>Then place linked locations, encounters, notes, and portals.</small></div>'}${(map.pins||[]).map(p=>`<button class="map-pin" data-map-pin="${p.id}" style="left:${p.x}%;top:${p.y}%;--pin:${esc(p.color||'#d4aa57')}" title="${esc(p.title)}"><span>${esc(p.icon||'●')}</span><b>${esc(p.title)}</b></button>`).join('')}</div><div class="atlas-legend">${(map.pins||[]).map(p=>`<button data-map-pin="${p.id}"><i style="background:${esc(p.color||'#d4aa57')}"></i>${esc(p.title)}</button>`).join('')||'<span>No pins placed.</span>'}</div>`:'<div class="empty-workspace">Create a map.</div>'}</section></div>`},
  timeline(){const w=StudioData.world(),events=[...w.timelineEvents].sort((a,b)=>String(a.dateStart).localeCompare(String(b.dateStart)));return `<div class="workspace-grid"><section class="workspace-card span-12"><div class="card-head"><div><span class="eyebrow">CHRONICLE</span><h2>World Timeline</h2></div><button class="primary" data-new-timeline-event>＋ Event</button></div><div class="timeline">${events.map((ev,i)=>`<article class="timeline-event" data-edit-timeline-event="${ev.id}"><div class="timeline-marker">${i+1}</div><div><time>${esc(ev.dateLabel||ev.dateStart||'Undated')}</time><h3>${esc(ev.title)}</h3><p>${esc(ev.description||'')}</p><div>${(ev.tags||[]).map(t=>`<span class="tag-pill">#${esc(t)}</span>`).join(' ')}</div></div></article>`).join('')||'<div class="empty-workspace">No historical events yet.</div>'}</div></section></div>`},
  relations(){const w=StudioData.world(),nodes=w.articles.slice(0,30),pairs=[];for(const a of nodes)for(const b of StudioData.articleLinks(a.content))if(nodes.some(n=>n.id===b.id))pairs.push([a,b]);const radius=210,cx=300,cy=260;return `<div class="workspace-grid"><section class="workspace-card span-8"><div class="card-head"><h2>Relationship graph</h2><button data-new-relation>＋ Manual relation</button></div><svg class="relation-graph" viewBox="0 0 600 520" role="img" aria-label="Linked world articles">${pairs.map(([a,b])=>{const ai=nodes.indexOf(a),bi=nodes.indexOf(b),ax=cx+Math.cos(ai/nodes.length*Math.PI*2)*radius,ay=cy+Math.sin(ai/nodes.length*Math.PI*2)*radius,bx=cx+Math.cos(bi/nodes.length*Math.PI*2)*radius,by=cy+Math.sin(bi/nodes.length*Math.PI*2)*radius;return `<line x1="${ax}" y1="${ay}" x2="${bx}" y2="${by}"/>`}).join('')}${nodes.map((a,i)=>{const x=cx+Math.cos(i/nodes.length*Math.PI*2)*radius,y=cy+Math.sin(i/nodes.length*Math.PI*2)*radius;return `<g class="relation-node" data-open-article="${a.id}" transform="translate(${x} ${y})"><circle r="24"/><text text-anchor="middle" dy="4">${esc((a.title||'?').slice(0,2).toUpperCase())}</text><title>${esc(a.title)}</title></g>`}).join('')}</svg></section><section class="workspace-card span-4"><div class="card-head"><h2>Connections</h2></div><div class="document-list">${pairs.slice(0,30).map(([a,b])=>`<article class="relation-row"><button data-open-article="${a.id}">${esc(a.title)}</button><span>→</span><button data-open-article="${b.id}">${esc(b.title)}</button></article>`).join('')||'<div class="empty-workspace">Add [[Article Links]] to article text.</div>'}${w.relations.map(r=>`<article class="relation-row"><button data-open-article="${r.fromId}">${esc(StudioData.article(r.fromId)?.title||'Unknown')}</button><span>${esc(r.type||'related to')}</span><button data-open-article="${r.toId}">${esc(StudioData.article(r.toId)?.title||'Unknown')}</button></article>`).join('')}</div></section></div>`},
  templates(){return `<div class="workspace-grid"><section class="workspace-card span-12"><div class="card-head"><div><span class="eyebrow">WORLD BUILDING TEMPLATES</span><h2>Create structured lore quickly</h2></div></div><div class="template-grid">${StudioData.templates.map(t=>`<article class="template-card large"><span>${t.icon}</span><h3>${esc(t.name)}</h3><p>${t.fields.map(f=>esc(f)).join(' · ')}</p><button class="primary" data-new-from-template="${t.id}">Create article</button></article>`).join('')}</div></section></div>`},
  portable(){return `<div class="workspace-grid"><section class="workspace-card span-6"><div class="card-head"><h2>Export campaign package</h2></div><p class="long-copy">Creates a ZIP with a complete TableGate project JSON, Markdown articles, campaign metadata, and embedded map/token/portrait assets when available.</p><div class="workspace-actions"><button class="primary" data-export-studio>Export ZIP</button><button data-export-studio-json>Export JSON only</button></div></section><section class="workspace-card span-6"><div class="card-head"><h2>Import or merge</h2></div><p class="long-copy">Import a TableGate JSON or ZIP package. Replace restores the package exactly; merge adds articles, maps, scenes, characters, handouts, timeline events, and relationships with new IDs when needed.</p><label class="drop-zone small"><span class="drop-icon">⇧</span><b>Choose campaign package</b><input type="file" id="studio-import-input" accept=".json,.zip,application/json,application/zip"></label><div class="field"><label>Import mode</label><select id="studio-import-mode"><option value="merge">Merge into current campaign</option><option value="replace">Replace current studio</option></select></div></section><section class="workspace-card span-12"><div class="card-head"><h2>Storage and synchronization</h2></div><div class="sync-status"><span class="status-pill ${StudioData.backendSupported===true?'approved':StudioData.backendSupported===false?'pending':''}">${StudioData.backendSupported===true?'Backend sync active':StudioData.backendSupported===false?'Local-first mode':'Sync not tested yet'}</span><span>Autosaved in this browser · ${StudioData.lastSyncedAt?`last backend save ${esc(new Date(StudioData.lastSyncedAt).toLocaleString())}`:'portable export recommended for backup'}</span></div><label class="list-row"><input type="checkbox" id="studio-backend-sync" ${StudioData.data.settings.backendSync!==false?'checked':''}> Attempt shared studio sync through the configured Apps Script backend</label></section></div>`},
  async handleClick(e){
    const tab=e.target.closest('[data-world-tab]');if(tab){StudioData.world().activeTab=tab.dataset.worldTab;StudioData.save();Workspace.render();return true}
    const newArticle=e.target.closest('[data-new-article],[data-new-from-template]');if(newArticle){this.openArticleCreate(newArticle.dataset.newFromTemplate||'location');return true}
    const open=e.target.closest('[data-open-article]');if(open){StudioData.world().selectedArticleId=open.dataset.openArticle;StudioData.world().activeTab='articles';StudioData.save();Workspace.render();return true}
    const save=e.target.closest('[data-save-article]');if(save){this.saveArticle(save.dataset.saveArticle);return true}
    const del=e.target.closest('[data-delete-article]');if(del){this.deleteArticle(del.dataset.deleteArticle);return true}
    const prev=e.target.closest('[data-preview-article]');if(prev){this.previewArticle(prev.dataset.previewArticle);return true}
    if(e.target.closest('[data-edit-world-profile]')){this.editWorldProfile();return true}
    if(e.target.closest('[data-manage-categories]')){this.manageCategories();return true}
    if(e.target.closest('[data-new-map]')){this.newMap();return true}
    const selectMap=e.target.closest('[data-select-map]');if(selectMap){StudioData.world().selectedMapId=selectMap.dataset.selectMap;StudioData.save();Workspace.render();return true}
    if(e.target.closest('[data-toggle-pin-mode]')){StudioData.world().pinMode=!StudioData.world().pinMode;StudioData.save();Workspace.render();return true}
    const mapPin=e.target.closest('[data-map-pin]');if(mapPin){this.editPin(mapPin.dataset.mapPin);return true}
    const map=e.target.closest('[data-atlas-map]');if(map&&StudioData.world().pinMode){const r=map.getBoundingClientRect(),x=((e.clientX-r.left)/r.width*100).toFixed(3),y=((e.clientY-r.top)/r.height*100).toFixed(3);this.editPin(null,{x:+x,y:+y});return true}
    const editMap=e.target.closest('[data-edit-map]');if(editMap){this.editMap(editMap.dataset.editMap);return true}
    if(e.target.closest('[data-new-timeline-event]')){this.editTimelineEvent();return true}
    const editEvent=e.target.closest('[data-edit-timeline-event]');if(editEvent){this.editTimelineEvent(editEvent.dataset.editTimelineEvent);return true}
    if(e.target.closest('[data-new-relation]')){this.newRelation();return true}
    if(e.target.closest('[data-export-studio]')){await this.exportZip();return true}
    if(e.target.closest('[data-export-studio-json]')){StudioData.download(`${this.slug(StudioData.world().name)}.tablegate.json`,new Blob([JSON.stringify(StudioData.data,null,2)],{type:'application/json'}));return true}
    return false;
  },
  bind(shell){
    const search=shell.querySelector('#world-article-search');if(search)search.oninput=()=>{StudioData.world().search=search.value;StudioData.save();clearTimeout(search._t);search._t=setTimeout(()=>Workspace.render(),180)};
    const filter=shell.querySelector('#world-category-filter');if(filter)filter.onchange=()=>{StudioData.world().categoryFilter=filter.value;StudioData.save();Workspace.render()};
    const atlasInput=shell.querySelector('#atlas-image-input');if(atlasInput)atlasInput.onchange=async()=>{const file=atlasInput.files[0];if(!file)return;const map=StudioData.world().maps.find(m=>m.id===StudioData.world().selectedMapId);map.imageDataUrl=await StudioData.fileToDataUrl(file);map.imageName=file.name;const img=new Image();img.onload=()=>{map.width=img.naturalWidth;map.height=img.naturalHeight;StudioData.save(true);Workspace.render()};img.src=map.imageDataUrl};
    const importInput=shell.querySelector('#studio-import-input');if(importInput)importInput.onchange=()=>this.importPackage(importInput.files[0],shell.querySelector('#studio-import-mode')?.value||'merge').catch(showError);
    const sync=shell.querySelector('#studio-backend-sync');if(sync)sync.onchange=()=>{StudioData.data.settings.backendSync=sync.checked;StudioData.backendSupported=null;StudioData.save(true)};
  },
  openArticleCreate(template='location'){const t=StudioData.templates.find(x=>x.id===template)||StudioData.templates[0];modal(`New ${t.name}`,`<div class="field"><label>Title</label><input id="new-article-title" autofocus></div><div class="field"><label>Category</label><select id="new-article-category">${StudioData.world().categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}<option>Uncategorized</option></select></div><div class="info-box">The ${esc(t.name)} template begins with sections for ${esc(t.fields.join(', '))}.</div>`,`<button data-close-modal>Cancel</button><button class="primary" data-create-article>Create article</button>`);$('#modal-root').querySelector('[data-create-article]').onclick=()=>{const title=$('#new-article-title').value.trim();if(!title)return toast('Enter an article title.','error');const now=new Date().toISOString(),id=uid(),content=t.fields.map(f=>`## ${f}\n\n`).join('\n');StudioData.world().articles.push({id,title,template:t.id,category:$('#new-article-category').value,status:'draft',visibility:'party',tags:[],excerpt:'',content,createdAt:now,updatedAt:now});StudioData.world().selectedArticleId=id;StudioData.world().activeTab='articles';StudioData.save(true);closeModal();Workspace.render()};setTimeout(()=>$('#new-article-title')?.focus(),40)},
  saveArticle(id){const a=StudioData.article(id);if(!a)return;Object.assign(a,{title:$('#article-title').value.trim()||'Untitled',template:$('#article-template').value,category:$('#article-category').value,tags:cleanTags($('#article-tags').value),status:$('#article-status').value,visibility:$('#article-visibility').value,excerpt:$('#article-excerpt').value,content:$('#article-content').value,updatedAt:new Date().toISOString()});StudioData.save(true);Workspace.render();toast('Article saved.','success')},
  deleteArticle(id){const a=StudioData.article(id);if(!a||!confirm(`Delete “${a.title}”?`))return;StudioData.world().articles=StudioData.world().articles.filter(x=>x.id!==id);StudioData.world().selectedArticleId=StudioData.world().articles[0]?.id||'';StudioData.world().relations=StudioData.world().relations.filter(r=>r.fromId!==id&&r.toId!==id);for(const m of StudioData.world().maps)m.pins=(m.pins||[]).map(p=>p.articleId===id?{...p,articleId:''}:p);StudioData.save(true);Workspace.render()},
  previewArticle(id){const a=StudioData.article(id);if(!a)return;modal(a.title,`<article class="article-preview"><p class="article-deck">${esc(a.excerpt||'')}</p>${StudioData.markdown(a.content)}<footer>${(a.tags||[]).map(t=>`<span class="tag-pill">#${esc(t)}</span>`).join(' ')}</footer></article>`,`<button data-close-modal>Close</button>`,'wide')},
  editWorldProfile(){const w=StudioData.world();modal('World profile',`<div class="field"><label>World name</label><input id="world-name" value="${esc(w.name)}"></div><div class="field"><label>Subtitle</label><input id="world-subtitle" value="${esc(w.subtitle)}"></div><div class="field"><label>Campaign summary</label><textarea id="world-summary" rows="6">${esc(w.summary)}</textarea></div>`,`<button data-close-modal>Cancel</button><button class="primary" data-save-world-profile>Save</button>`);$('#modal-root').querySelector('[data-save-world-profile]').onclick=()=>{w.name=$('#world-name').value.trim()||'Untitled World';w.subtitle=$('#world-subtitle').value.trim();w.summary=$('#world-summary').value;StudioData.save(true);closeModal();Workspace.render()}},
  manageCategories(){const w=StudioData.world();modal('Article categories',`<div class="document-list" id="category-list">${w.categories.map(c=>`<div class="split"><input data-category-name="${c.id}" value="${esc(c.name)}"><button class="danger" data-remove-category="${c.id}">Delete</button></div>`).join('')}</div><div class="split" style="margin-top:12px"><input id="new-category-name" placeholder="New category"><button data-add-category>Add</button></div>`,`<button data-close-modal>Cancel</button><button class="primary" data-save-categories>Save</button>`);const root=$('#modal-root');root.onclick=e=>{const rm=e.target.closest('[data-remove-category]');if(rm){root.querySelector(`[data-category-name="${CSS.escape(rm.dataset.removeCategory)}"]`)?.closest('.split')?.remove()}if(e.target.closest('[data-add-category]')){const name=$('#new-category-name').value.trim();if(name){root.querySelector('#category-list').insertAdjacentHTML('beforeend',`<div class="split"><input data-category-name="${uid()}" value="${esc(name)}"><button class="danger" data-remove-category>Delete</button></div>`);$('#new-category-name').value=''}}};root.querySelector('[data-save-categories]').onclick=()=>{const old=new Map(w.categories.map(c=>[c.id,c.name]));w.categories=[...root.querySelectorAll('[data-category-name]')].map(i=>({id:i.dataset.categoryName,name:i.value.trim()||'Untitled',parentId:'',icon:'📁'}));for(const a of w.articles){const found=[...old].find(([,name])=>name===a.category);if(found){const replacement=w.categories.find(c=>c.id===found[0]);a.category=replacement?.name||'Uncategorized'}}StudioData.save(true);closeModal();Workspace.render()}},
  newMap(){modal('New map',`<div class="field"><label>Map name</label><input id="new-map-name" value="New Map"></div><div class="field"><label>Notes</label><textarea id="new-map-notes" rows="3"></textarea></div>`,`<button data-close-modal>Cancel</button><button class="primary" data-create-map>Create map</button>`);$('#modal-root').querySelector('[data-create-map]').onclick=()=>{const id=uid();StudioData.world().maps.push({id,name:$('#new-map-name').value.trim()||'New Map',notes:$('#new-map-notes').value,imageDataUrl:'',width:1600,height:1000,pins:[],createdAt:new Date().toISOString()});StudioData.world().selectedMapId=id;StudioData.save(true);closeModal();Workspace.render()}},
  editMap(id){const m=StudioData.world().maps.find(x=>x.id===id);if(!m)return;modal('Map settings',`<div class="field"><label>Name</label><input id="map-name" value="${esc(m.name)}"></div><div class="field"><label>Notes</label><textarea id="map-notes" rows="4">${esc(m.notes||'')}</textarea></div>`,`<button class="danger" data-delete-map>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-map>Save</button>`);const root=$('#modal-root');root.querySelector('[data-save-map]').onclick=()=>{m.name=$('#map-name').value.trim()||'Map';m.notes=$('#map-notes').value;StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-map]').onclick=()=>{if(!confirm(`Delete ${m.name}?`))return;StudioData.world().maps=StudioData.world().maps.filter(x=>x.id!==id);StudioData.world().selectedMapId=StudioData.world().maps[0]?.id||'';StudioData.save(true);closeModal();Workspace.render()}},
  editPin(id=null,pos={x:50,y:50}){const map=StudioData.world().maps.find(m=>m.id===StudioData.world().selectedMapId),p=map?.pins.find(x=>x.id===id);if(!map)return;modal(p?'Edit map pin':'Place map pin',`<div class="split"><div class="field"><label>Title</label><input id="pin-title" value="${esc(p?.title||'New Location')}"></div><div class="field"><label>Icon</label><input id="pin-icon" maxlength="4" value="${esc(p?.icon||'●')}"></div></div><div class="split"><div class="field"><label>Color</label><input id="pin-color" type="color" value="${esc(p?.color||'#d4aa57')}"></div><div class="field"><label>Linked article</label><select id="pin-article"><option value="">None</option>${StudioData.world().articles.map(a=>`<option value="${a.id}" ${p?.articleId===a.id?'selected':''}>${esc(a.title)}</option>`).join('')}</select></div></div><div class="field"><label>Notes</label><textarea id="pin-notes" rows="4">${esc(p?.notes||'')}</textarea></div>`,`<button class="danger" data-delete-pin ${p?'':'disabled'}>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-pin>Save</button>`);const root=$('#modal-root');root.querySelector('[data-save-pin]').onclick=()=>{const next={id:p?.id||uid(),x:p?.x??pos.x,y:p?.y??pos.y,title:$('#pin-title').value.trim()||'Pin',icon:$('#pin-icon').value||'●',color:$('#pin-color').value,articleId:$('#pin-article').value,notes:$('#pin-notes').value};if(p)Object.assign(p,next);else map.pins.push(next);StudioData.world().pinMode=false;StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-pin]')?.addEventListener('click',()=>{map.pins=map.pins.filter(x=>x.id!==p.id);StudioData.save(true);closeModal();Workspace.render()})},
  editTimelineEvent(id=null){const w=StudioData.world(),ev=w.timelineEvents.find(x=>x.id===id);modal(ev?'Edit timeline event':'New timeline event',`<div class="field"><label>Title</label><input id="timeline-title" value="${esc(ev?.title||'')}"></div><div class="split"><div class="field"><label>Sortable date</label><input id="timeline-date" value="${esc(ev?.dateStart||'')}" placeholder="0001-01-01 or campaign date"></div><div class="field"><label>Displayed date</label><input id="timeline-label" value="${esc(ev?.dateLabel||'')}" placeholder="Age of Embers, Year 14"></div></div><div class="field"><label>Description</label><textarea id="timeline-description" rows="6">${esc(ev?.description||'')}</textarea></div><div class="field"><label>Tags</label><input id="timeline-tags" value="${esc((ev?.tags||[]).join(', '))}"></div>`,`<button class="danger" data-delete-timeline ${ev?'':'disabled'}>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-timeline>Save</button>`);const root=$('#modal-root');root.querySelector('[data-save-timeline]').onclick=()=>{const next={id:ev?.id||uid(),title:$('#timeline-title').value.trim()||'Untitled event',dateStart:$('#timeline-date').value,dateLabel:$('#timeline-label').value,description:$('#timeline-description').value,tags:cleanTags($('#timeline-tags').value)};if(ev)Object.assign(ev,next);else w.timelineEvents.push(next);StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-timeline]')?.addEventListener('click',()=>{w.timelineEvents=w.timelineEvents.filter(x=>x.id!==ev.id);StudioData.save(true);closeModal();Workspace.render()})},
  newRelation(){const arts=StudioData.world().articles;if(arts.length<2)return toast('Create at least two articles first.','error');modal('Add relationship',`<div class="field"><label>From</label><select id="relation-from">${arts.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></div><div class="field"><label>Relationship</label><input id="relation-type" value="related to"></div><div class="field"><label>To</label><select id="relation-to">${arts.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></div>`,`<button data-close-modal>Cancel</button><button class="primary" data-save-relation>Save</button>`);$('#modal-root').querySelector('[data-save-relation]').onclick=()=>{StudioData.world().relations.push({id:uid(),fromId:$('#relation-from').value,toId:$('#relation-to').value,type:$('#relation-type').value.trim()||'related to'});StudioData.save(true);closeModal();Workspace.render()}},
  slug(v){return String(v||'campaign').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'campaign'},
  dataUrlBlob(dataUrl){const [head,data]=dataUrl.split(','),mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream',bytes=atob(data),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:mime})},
  async exportZip(){const zip=new JSZip(),slug=this.slug(StudioData.world().name),clone=typeof structuredClone==='function'?structuredClone(StudioData.data):JSON.parse(JSON.stringify(StudioData.data));zip.file('project.tablegate.json',JSON.stringify(clone,null,2));zip.file('README.md',`# ${StudioData.world().name}\n\nPortable TableGate campaign package. Import project.tablegate.json through World → Import / Export.\n`);const articleDir=zip.folder('articles');for(const a of clone.world.articles)articleDir.file(`${this.slug(a.title)}-${a.id.slice(0,8)}.md`,`# ${a.title}\n\n${a.excerpt||''}\n\n${a.content||''}\n\nTags: ${(a.tags||[]).join(', ')}`);const assets=zip.folder('assets');for(const m of clone.world.maps){if(m.imageDataUrl?.startsWith('data:')){const ext=(m.imageDataUrl.match(/^data:image\/([^;]+)/)||[])[1]||'png';assets.file(`maps/${m.id}.${ext}`,this.dataUrlBlob(m.imageDataUrl))}}for(const c of clone.vtt.characters){for(const [kind,key] of [['portraits','portraitDataUrl'],['tokens','tokenDataUrl']])if(c[key]?.startsWith('data:')){const ext=(c[key].match(/^data:image\/([^;]+)/)||[])[1]||'png';assets.file(`${kind}/${c.id}.${ext}`,this.dataUrlBlob(c[key]))}}for(const s of clone.vtt.scenes)if(s.backgroundDataUrl?.startsWith('data:')){const ext=(s.backgroundDataUrl.match(/^data:image\/([^;]+)/)||[])[1]||'png';assets.file(`scenes/${s.id}.${ext}`,this.dataUrlBlob(s.backgroundDataUrl))}const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});StudioData.download(`${slug}.tablegate.zip`,blob);toast('Campaign package exported.','success')},
  async importPackage(file,mode='merge'){if(!file)return;let incoming;if(file.name.toLowerCase().endsWith('.zip')){const zip=await JSZip.loadAsync(file),entry=zip.file('project.tablegate.json')||Object.values(zip.files).find(x=>x.name.endsWith('.tablegate.json'));if(!entry)throw new Error('This ZIP does not contain project.tablegate.json.');incoming=JSON.parse(await entry.async('text'))}else incoming=JSON.parse(await file.text());if(mode==='replace'){StudioData.data=StudioData.normalize(incoming)}else this.merge(incoming);StudioData.save(true);Workspace.render();toast(`Campaign ${mode==='replace'?'restored':'merged'}.`,'success')},
  merge(incoming){const src=StudioData.normalize(incoming),dst=StudioData.data,idMap=new Map(),mergeArr=(target,items)=>{for(const original of items||[]){const item=JSON.parse(JSON.stringify(original));if(target.some(x=>x.id===item.id)){const old=item.id;item.id=uid();idMap.set(old,item.id)}target.push(item)}};mergeArr(dst.world.articles,src.world.articles);mergeArr(dst.world.maps,src.world.maps);mergeArr(dst.world.timelineEvents,src.world.timelineEvents);mergeArr(dst.world.relations,src.world.relations);mergeArr(dst.vtt.scenes,src.vtt.scenes);mergeArr(dst.vtt.characters,src.vtt.characters);mergeArr(dst.vtt.handouts,src.vtt.handouts);for(const a of dst.world.articles)if(idMap.has(a.id))a.id=idMap.get(a.id);for(const r of dst.world.relations){r.fromId=idMap.get(r.fromId)||r.fromId;r.toId=idMap.get(r.toId)||r.toId}for(const m of dst.world.maps)for(const p of m.pins||[])p.articleId=idMap.get(p.articleId)||p.articleId}
};

const VTTStudio={
  canvas:null,ctx:null,imageCache:new Map(),drag:null,drawing:null,measure:null,
  async ensure(){await StudioData.load()},
  render(){const v=StudioData.vtt();return `<div class="studio-shell vtt-studio"><div class="studio-subnav">${[['table','Tabletop'],['characters','Characters'],['handouts','Handouts'],['dice','Dice & Log']].map(([id,label])=>`<button data-vtt-tab="${id}" class="${v.activeTab===id?'active':''}">${label}</button>`).join('')}</div><div id="vtt-studio-content">${this.renderTab(v.activeTab)}</div></div>`},
  renderTab(tab){if(tab==='characters')return this.characters();if(tab==='handouts')return this.handouts();if(tab==='dice')return this.dice();return this.table()},
  table(){const v=StudioData.vtt(),s=StudioData.scene();return `<div class="vtt-layout"><section class="vtt-board-panel workspace-card"><div class="vtt-toolbar"><select id="vtt-scene-select">${v.scenes.map(x=>`<option value="${x.id}" ${x.id===s?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button data-new-scene title="New scene">＋ Scene</button><label class="file-button" title="Upload scene background">Map<input type="file" id="vtt-background-input" accept="image/*"></label><span class="tool-sep"></span>${[['select','↖','Select'],['token','♟','Add token'],['draw','✎','Draw'],['measure','↔','Measure'],['fog','▦','Add fog'],['reveal','◫','Reveal']].map(([id,icon,label])=>`<button data-vtt-tool="${id}" class="${v.tool===id?'active':''}" title="${label}">${icon}</button>`).join('')}<span class="tool-sep"></span><button data-vtt-zoom="-0.1">−</button><span class="zoom-readout">${Math.round(v.zoom*100)}%</span><button data-vtt-zoom="0.1">＋</button><button data-fit-vtt>Fit</button><label class="toggle-label"><input type="checkbox" id="vtt-grid-toggle" ${s?.gridEnabled!==false?'checked':''}> Grid</label><button data-scene-settings>⚙</button></div><div class="vtt-stage-wrap" id="vtt-stage-wrap"><canvas id="vtt-canvas" width="1200" height="720" aria-label="Virtual tabletop"></canvas><div id="vtt-measure-label" class="measure-label hidden"></div></div></section><aside class="vtt-side"><section class="workspace-card initiative-panel"><div class="card-head"><div><span class="eyebrow">ROUND ${v.round}</span><h2>Initiative</h2></div><div class="workspace-actions"><button data-add-initiative>＋</button><button data-sort-initiative>⇅</button></div></div><div class="initiative-list">${v.initiative.map((it,i)=>`<article class="initiative-row ${i===v.turnIndex?'active':''}" data-initiative-id="${it.id}"><button data-set-turn="${i}">${i===v.turnIndex?'▶':'○'}</button><span class="token-dot" style="background:${esc(it.color||'#d4aa57')}"></span><b>${esc(it.name)}</b><input type="number" data-initiative-score="${it.id}" value="${Number(it.score)||0}"><button data-remove-initiative="${it.id}">×</button></article>`).join('')||'<div class="empty-workspace">Add combatants.</div>'}</div><div class="workspace-actions full"><button data-prev-turn>← Previous</button><button class="primary" data-next-turn>Next →</button></div></section><section class="workspace-card scene-roster"><div class="card-head"><h2>Scene tokens</h2><button data-add-token>＋</button></div><div class="token-roster">${(s?.tokens||[]).map(t=>`<button data-select-token="${t.id}" class="${v.selectedTokenId===t.id?'active':''}"><span class="token-dot" style="background:${esc(t.color||'#d4aa57')};${t.imageDataUrl?`background-image:url('${t.imageDataUrl}')`:''}"></span><span><b>${esc(t.name)}</b><small>${t.hidden?'Hidden':'Visible'} · ${t.size||1}×</small></span></button>`).join('')||'<div class="empty-workspace">No tokens on this scene.</div>'}</div></section><section class="workspace-card quick-dice"><div class="card-head"><h2>Quick dice</h2></div><div class="dice-buttons">${[4,6,8,10,12,20,100].map(d=>`<button data-quick-die="${d}">d${d}</button>`).join('')}</div><div class="quick-roll-result">${v.diceLog[0]?`<b>${esc(v.diceLog[0].expression)} = ${v.diceLog[0].total}</b><small>${esc(v.diceLog[0].detail)}</small>`:'Roll from the table.'}</div></section></aside></div>`},
  characters(){const chars=StudioData.vtt().characters;return `<div class="workspace-grid"><section class="workspace-card span-12"><div class="card-head"><div><span class="eyebrow">CAMPAIGN ROSTER</span><h2>Characters & NPCs</h2></div><button class="primary" data-new-character>＋ Character</button></div><div class="character-grid">${chars.map(c=>`<article class="character-card" data-edit-character="${c.id}"><div class="character-portrait" style="${c.portraitDataUrl?`background-image:url('${c.portraitDataUrl}')`:''}">${c.portraitDataUrl?'':esc(initials(c.name))}</div><div><span class="eyebrow">${esc(c.system||'SYSTEM NEUTRAL')}</span><h3>${esc(c.name)}</h3><p>${esc(c.player||'Unassigned player')}</p><div class="character-stats"><span>HP <b>${c.hp}/${c.maxHp}</b></span><span>AC <b>${c.ac}</b></span><span>Speed <b>${esc(c.speed)}</b></span></div></div><button data-character-to-scene="${c.id}">Add to scene</button></article>`).join('')||'<div class="empty-workspace">No characters yet.</div>'}</div></section></div>`},
  handouts(){const items=StudioData.vtt().handouts;return `<div class="workspace-grid"><section class="workspace-card span-12"><div class="card-head"><div><span class="eyebrow">PLAYER MATERIALS</span><h2>Handouts & Notes</h2></div><button class="primary" data-new-handout>＋ Handout</button></div><div class="handout-grid">${items.map(h=>`<article class="handout-card" data-edit-handout="${h.id}"><div class="handout-icon">${h.imageDataUrl?'🖼':'📄'}</div><div><span class="status-pill ${h.visibility==='party'?'approved':'pending'}">${esc(h.visibility||'runner')}</span><h3>${esc(h.title)}</h3><p>${esc(h.summary||'')}</p></div></article>`).join('')||'<div class="empty-workspace">Create notes, clues, images, letters, rules, and player handouts.</div>'}</div></section></div>`},
  dice(){const v=StudioData.vtt();return `<div class="workspace-grid"><section class="workspace-card span-5"><div class="card-head"><h2>Dice roller</h2></div><div class="dice-console"><input id="vtt-dice-expression" value="1d20" placeholder="2d6+3, 1d20kh1"><button class="primary" data-roll-expression>Roll</button></div><div class="dice-buttons large">${[4,6,8,10,12,20,100].map(d=>`<button data-quick-die="${d}">d${d}</button>`).join('')}</div><div class="roll-hero">${v.diceLog[0]?`<span>${esc(v.diceLog[0].expression)}</span><strong>${v.diceLog[0].total}</strong><p>${esc(v.diceLog[0].detail)}</p>`:'<span>Ready</span><strong>—</strong><p>Supports standard NdM±K expressions.</p>'}</div></section><section class="workspace-card span-7"><div class="card-head"><h2>Campaign roll log</h2><button data-clear-dice-log>Clear</button></div><div class="dice-log">${v.diceLog.map(r=>`<article><div><b>${esc(r.user||'Player')}</b><small>${esc(new Date(r.at).toLocaleString())}</small></div><code>${esc(r.expression)}</code><strong>${r.total}</strong><span>${esc(r.detail)}</span></article>`).join('')||'<div class="empty-workspace">No rolls yet.</div>'}</div></section></div>`},
  async handleClick(e){
    const tab=e.target.closest('[data-vtt-tab]');if(tab){StudioData.vtt().activeTab=tab.dataset.vttTab;StudioData.save();Workspace.render();return true}
    const tool=e.target.closest('[data-vtt-tool]');if(tool){StudioData.vtt().tool=tool.dataset.vttTool;StudioData.save();Workspace.render();return true}
    const zoom=e.target.closest('[data-vtt-zoom]');if(zoom){StudioData.vtt().zoom=Math.max(.2,Math.min(3,StudioData.vtt().zoom+Number(zoom.dataset.vttZoom)));StudioData.save();Workspace.render();return true}
    if(e.target.closest('[data-fit-vtt]')){this.fit();return true}
    if(e.target.closest('[data-new-scene]')){this.newScene();return true}
    if(e.target.closest('[data-scene-settings]')){this.sceneSettings();return true}
    if(e.target.closest('[data-add-token]')){this.addToken();return true}
    const select=e.target.closest('[data-select-token]');if(select){StudioData.vtt().selectedTokenId=select.dataset.selectToken;StudioData.save();this.draw();Workspace.render();return true}
    if(e.target.closest('[data-add-initiative]')){this.addInitiative();return true}
    if(e.target.closest('[data-sort-initiative]')){StudioData.vtt().initiative.sort((a,b)=>b.score-a.score);StudioData.vtt().turnIndex=0;StudioData.save();Workspace.render();return true}
    const removeInit=e.target.closest('[data-remove-initiative]');if(removeInit){StudioData.vtt().initiative=StudioData.vtt().initiative.filter(x=>x.id!==removeInit.dataset.removeInitiative);StudioData.vtt().turnIndex=Math.min(StudioData.vtt().turnIndex,Math.max(0,StudioData.vtt().initiative.length-1));StudioData.save();Workspace.render();return true}
    const setTurn=e.target.closest('[data-set-turn]');if(setTurn){StudioData.vtt().turnIndex=+setTurn.dataset.setTurn;StudioData.save();Workspace.render();return true}
    if(e.target.closest('[data-next-turn]')){this.nextTurn(1);return true}if(e.target.closest('[data-prev-turn]')){this.nextTurn(-1);return true}
    const die=e.target.closest('[data-quick-die]');if(die){this.roll(`1d${die.dataset.quickDie}`);return true}
    if(e.target.closest('[data-roll-expression]')){this.roll($('#vtt-dice-expression')?.value||'1d20');return true}
    if(e.target.closest('[data-clear-dice-log]')){if(confirm('Clear the local dice log?')){StudioData.vtt().diceLog=[];StudioData.save();Workspace.render()}return true}
    if(e.target.closest('[data-new-character]')){this.editCharacter();return true}
    const editChar=e.target.closest('[data-edit-character]');if(editChar&&!e.target.closest('[data-character-to-scene]')){this.editCharacter(editChar.dataset.editCharacter);return true}
    const charScene=e.target.closest('[data-character-to-scene]');if(charScene){this.characterToScene(charScene.dataset.characterToScene);return true}
    if(e.target.closest('[data-new-handout]')){this.editHandout();return true}
    const editHand=e.target.closest('[data-edit-handout]');if(editHand){this.editHandout(editHand.dataset.editHandout);return true}
    return false;
  },
  bind(shell){
    const sceneSelect=shell.querySelector('#vtt-scene-select');if(sceneSelect)sceneSelect.onchange=()=>{StudioData.vtt().activeSceneId=sceneSelect.value;StudioData.vtt().selectedTokenId='';StudioData.save();Workspace.render()};
    const bg=shell.querySelector('#vtt-background-input');if(bg)bg.onchange=async()=>{const file=bg.files[0],s=StudioData.scene();if(!file||!s)return;s.backgroundDataUrl=await StudioData.fileToDataUrl(file);s.backgroundName=file.name;const img=new Image();img.onload=()=>{s.width=img.naturalWidth;s.height=img.naturalHeight;StudioData.save(true);Workspace.render()};img.src=s.backgroundDataUrl};
    const grid=shell.querySelector('#vtt-grid-toggle');if(grid)grid.onchange=()=>{StudioData.scene().gridEnabled=grid.checked;StudioData.save();this.draw()};
    shell.querySelectorAll('[data-initiative-score]').forEach(input=>input.onchange=()=>{const it=StudioData.vtt().initiative.find(x=>x.id===input.dataset.initiativeScore);if(it)it.score=Number(input.value)||0;StudioData.save()});
    const canvas=shell.querySelector('#vtt-canvas');if(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.resizeCanvas();this.bindCanvas(canvas);this.draw();window.__tablegateVttResize=()=>{if($('#vtt-canvas')){this.resizeCanvas();this.draw()}}}
  },
  resizeCanvas(){if(!this.canvas)return;const wrap=this.canvas.parentElement,r=wrap.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);this.canvas.width=Math.max(640,Math.floor(r.width*dpr));this.canvas.height=Math.max(420,Math.floor(r.height*dpr));this.canvas.style.width=`${r.width}px`;this.canvas.style.height=`${r.height}px`;this.ctx.setTransform(dpr,0,0,dpr,0,0);this.viewportWidth=r.width;this.viewportHeight=r.height},
  transform(){const s=StudioData.scene(),v=StudioData.vtt(),scale=Math.min((this.viewportWidth||1200)/s.width,(this.viewportHeight||720)/s.height)*v.zoom,ox=((this.viewportWidth||1200)-s.width*scale)/2+v.panX,oy=((this.viewportHeight||720)-s.height*scale)/2+v.panY;return {scale,ox,oy}},
  toWorld(clientX,clientY){const r=this.canvas.getBoundingClientRect(),{scale,ox,oy}=this.transform();return {x:(clientX-r.left-ox)/scale,y:(clientY-r.top-oy)/scale}},
  image(src){if(!src)return null;if(this.imageCache.has(src))return this.imageCache.get(src);const img=new Image();img.onload=()=>this.draw();img.src=src;this.imageCache.set(src,img);return img},
  draw(){if(!this.ctx||!this.canvas)return;const c=this.ctx,s=StudioData.scene(),v=StudioData.vtt();if(!s)return;const w=this.viewportWidth||this.canvas.width,h=this.viewportHeight||this.canvas.height,{scale,ox,oy}=this.transform();c.clearRect(0,0,w,h);c.fillStyle='#0b0e0c';c.fillRect(0,0,w,h);c.save();c.translate(ox,oy);c.scale(scale,scale);c.fillStyle='#1b201c';c.fillRect(0,0,s.width,s.height);const bg=this.image(s.backgroundDataUrl);if(bg?.complete&&bg.naturalWidth)c.drawImage(bg,0,0,s.width,s.height);else{c.fillStyle='#8b927f';c.font='36px Georgia';c.textAlign='center';c.fillText('Upload a scene map',s.width/2,s.height/2)}if(s.gridEnabled!==false){const size=s.gridSize||70;c.strokeStyle=s.gridColor||'rgba(255,255,255,.22)';c.lineWidth=1/scale;c.beginPath();for(let x=0;x<=s.width;x+=size){c.moveTo(x,0);c.lineTo(x,s.height)}for(let y=0;y<=s.height;y+=size){c.moveTo(0,y);c.lineTo(s.width,y)}c.stroke()}for(const d of s.drawings||[]){c.strokeStyle=d.color||'#ffcc66';c.lineWidth=(d.width||5)/scale;c.lineCap='round';c.beginPath();d.points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke()}for(const t of s.tokens||[]){if(t.hidden&&!isRunner())continue;const size=(s.gridSize||70)*(t.size||1),x=t.x-size/2,y=t.y-size/2;c.save();c.beginPath();c.arc(t.x,t.y,size/2,0,Math.PI*2);c.clip();const img=this.image(t.imageDataUrl);if(img?.complete&&img.naturalWidth)c.drawImage(img,x,y,size,size);else{c.fillStyle=t.color||'#d4aa57';c.fillRect(x,y,size,size);c.fillStyle='#171a18';c.font=`${Math.max(18,size*.3)}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(initials(t.name),t.x,t.y)}c.restore();c.strokeStyle=v.selectedTokenId===t.id?'#fff4bd':(t.color||'#d4aa57');c.lineWidth=(v.selectedTokenId===t.id?5:3)/scale;c.beginPath();c.arc(t.x,t.y,size/2,0,Math.PI*2);c.stroke();c.fillStyle='rgba(0,0,0,.78)';c.fillRect(t.x-size/2,t.y+size/2-18/scale,size,18/scale);c.fillStyle='#fff';c.font=`${12/scale}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(t.name,t.x,t.y+size/2-9/scale)}for(const f of s.fog||[]){c.fillStyle='rgba(0,0,0,.92)';c.fillRect(f.x,f.y,f.w,f.h)}if(this.drawing?.points?.length){c.strokeStyle='#ffcc66';c.lineWidth=5/scale;c.beginPath();this.drawing.points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke()}if(this.measure){c.strokeStyle='#ffef9a';c.lineWidth=3/scale;c.setLineDash([12/scale,8/scale]);c.beginPath();c.moveTo(this.measure.x1,this.measure.y1);c.lineTo(this.measure.x2,this.measure.y2);c.stroke();c.setLineDash([])}c.restore()},
  bindCanvas(canvas){
    canvas.oncontextmenu=e=>e.preventDefault();
    canvas.onpointerdown=e=>{const p=this.toWorld(e.clientX,e.clientY),s=StudioData.scene(),v=StudioData.vtt();canvas.setPointerCapture(e.pointerId);if(v.tool==='select'){const token=[...s.tokens].reverse().find(t=>Math.hypot(t.x-p.x,t.y-p.y)<(s.gridSize||70)*(t.size||1)/2);if(token){v.selectedTokenId=token.id;this.drag={kind:'token',token,start:p,origin:{x:token.x,y:token.y}}}else this.drag={kind:'pan',start:{x:e.clientX,y:e.clientY},origin:{x:v.panX,y:v.panY}}}else if(v.tool==='draw'){this.drawing={points:[p],color:'#ffcc66',width:5}}else if(v.tool==='measure'){this.measure={x1:p.x,y1:p.y,x2:p.x,y2:p.y}}else if(v.tool==='fog'||v.tool==='reveal'){this.drag={kind:v.tool,start:p,current:p}}else if(v.tool==='token')this.addToken(p);this.draw()};
    canvas.onpointermove=e=>{const p=this.toWorld(e.clientX,e.clientY),s=StudioData.scene(),v=StudioData.vtt();if(this.drag?.kind==='token'){let x=this.drag.origin.x+(p.x-this.drag.start.x),y=this.drag.origin.y+(p.y-this.drag.start.y);if(v.snap){const g=s.gridSize||70;x=Math.round(x/g)*g+g/2;y=Math.round(y/g)*g+g/2}this.drag.token.x=x;this.drag.token.y=y;this.draw()}else if(this.drag?.kind==='pan'){v.panX=this.drag.origin.x+(e.clientX-this.drag.start.x);v.panY=this.drag.origin.y+(e.clientY-this.drag.start.y);this.draw()}else if(this.drawing){this.drawing.points.push(p);this.draw()}else if(this.measure){this.measure.x2=p.x;this.measure.y2=p.y;const dist=Math.hypot(this.measure.x2-this.measure.x1,this.measure.y2-this.measure.y1),cells=dist/(s.gridSize||70),label=document.querySelector('#vtt-measure-label');if(label){label.classList.remove('hidden');label.style.left=`${e.clientX-canvas.getBoundingClientRect().left+12}px`;label.style.top=`${e.clientY-canvas.getBoundingClientRect().top+12}px`;label.textContent=`${cells.toFixed(1)} squares · ${Math.round(cells*5)} ft`}this.draw()}else if(this.drag&&['fog','reveal'].includes(this.drag.kind)){this.drag.current=p;this.draw();const {scale,ox,oy}=this.transform(),x=Math.min(this.drag.start.x,p.x),y=Math.min(this.drag.start.y,p.y),rw=Math.abs(p.x-this.drag.start.x),rh=Math.abs(p.y-this.drag.start.y);this.ctx.save();this.ctx.strokeStyle=this.drag.kind==='fog'?'#111':'#fff';this.ctx.lineWidth=2;this.ctx.strokeRect(ox+x*scale,oy+y*scale,rw*scale,rh*scale);this.ctx.restore()}};
    canvas.onpointerup=e=>{const s=StudioData.scene();if(this.drag?.kind==='token'||this.drag?.kind==='pan')StudioData.save();else if(this.drawing){if(this.drawing.points.length>1)s.drawings.push(this.drawing);this.drawing=null;StudioData.save()}else if(this.measure){this.measure=null;document.querySelector('#vtt-measure-label')?.classList.add('hidden')}else if(this.drag?.kind==='fog'){const a=this.drag.start,b=this.drag.current||a;s.fog.push({id:uid(),x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(a.x-b.x),h:Math.abs(a.y-b.y)});StudioData.save()}else if(this.drag?.kind==='reveal'){const a=this.drag.start,b=this.drag.current||a,x=Math.min(a.x,b.x),y=Math.min(a.y,b.y),w=Math.abs(a.x-b.x),h=Math.abs(a.y-b.y);s.fog=s.fog.filter(f=>!(f.x<x+w&&f.x+f.w>x&&f.y<y+h&&f.y+f.h>y));StudioData.save()}this.drag=null;this.draw();Workspace.render()};
    canvas.onwheel=e=>{e.preventDefault();StudioData.vtt().zoom=Math.max(.2,Math.min(3,StudioData.vtt().zoom+(e.deltaY<0?.1:-.1)));StudioData.save();this.draw()};
    canvas.ondblclick=e=>{const p=this.toWorld(e.clientX,e.clientY),s=StudioData.scene(),token=[...s.tokens].reverse().find(t=>Math.hypot(t.x-p.x,t.y-p.y)<(s.gridSize||70)*(t.size||1)/2);if(token)this.editToken(token.id)};
  },
  fit(){StudioData.vtt().zoom=1;StudioData.vtt().panX=0;StudioData.vtt().panY=0;StudioData.save();this.draw();Workspace.render()},
  newScene(){modal('New tabletop scene',`<div class="field"><label>Scene name</label><input id="new-scene-name" value="New Scene"></div><div class="split"><div class="field"><label>Width</label><input id="new-scene-width" type="number" value="1600"></div><div class="field"><label>Height</label><input id="new-scene-height" type="number" value="1000"></div></div>`,`<button data-close-modal>Cancel</button><button class="primary" data-create-scene>Create</button>`);$('#modal-root').querySelector('[data-create-scene]').onclick=()=>{const id=uid();StudioData.vtt().scenes.push({id,name:$('#new-scene-name').value.trim()||'New Scene',width:+$('#new-scene-width').value||1600,height:+$('#new-scene-height').value||1000,backgroundDataUrl:'',backgroundName:'',gridSize:70,gridEnabled:true,gridColor:'rgba(255,255,255,.22)',tokens:[],drawings:[],fog:[],notes:'',createdAt:new Date().toISOString()});StudioData.vtt().activeSceneId=id;StudioData.save(true);closeModal();Workspace.render()}},
  sceneSettings(){const s=StudioData.scene();if(!s)return;modal('Scene settings',`<div class="field"><label>Name</label><input id="scene-name" value="${esc(s.name)}"></div><div class="split"><div class="field"><label>Grid size (pixels)</label><input id="scene-grid-size" type="number" min="20" max="300" value="${s.gridSize||70}"></div><div class="field"><label>Grid color</label><input id="scene-grid-color" value="${esc(s.gridColor||'rgba(255,255,255,.22)')}"></div></div><div class="field"><label>Runner notes</label><textarea id="scene-notes" rows="5">${esc(s.notes||'')}</textarea></div><label class="list-row"><input id="scene-snap" type="checkbox" ${StudioData.vtt().snap?'checked':''}> Snap tokens to grid</label>`,`<button class="danger" data-delete-scene ${StudioData.vtt().scenes.length===1?'disabled':''}>Delete scene</button><button data-close-modal>Cancel</button><button data-clear-drawings>Clear drawings/fog</button><button class="primary" data-save-scene>Save</button>`);const root=$('#modal-root');root.querySelector('[data-save-scene]').onclick=()=>{s.name=$('#scene-name').value.trim()||'Scene';s.gridSize=Math.max(20,+$('#scene-grid-size').value||70);s.gridColor=$('#scene-grid-color').value||'rgba(255,255,255,.22)';s.notes=$('#scene-notes').value;StudioData.vtt().snap=$('#scene-snap').checked;StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-clear-drawings]').onclick=()=>{if(confirm('Clear all drawings and fog on this scene?')){s.drawings=[];s.fog=[];StudioData.save(true);closeModal();Workspace.render()}};root.querySelector('[data-delete-scene]')?.addEventListener('click',()=>{if(!confirm(`Delete ${s.name}?`))return;StudioData.vtt().scenes=StudioData.vtt().scenes.filter(x=>x.id!==s.id);StudioData.vtt().activeSceneId=StudioData.vtt().scenes[0].id;StudioData.save(true);closeModal();Workspace.render()})},
  addToken(pos=null){const s=StudioData.scene(),v=StudioData.vtt(),chars=v.characters;modal('Add token',`<div class="field"><label>Character</label><select id="token-character"><option value="">Custom token</option>${chars.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Name</label><input id="token-name" value="New Token"></div><div class="split"><div class="field"><label>Size in squares</label><input id="token-size" type="number" min="0.25" max="6" step="0.25" value="1"></div><div class="field"><label>Color</label><input id="token-color" type="color" value="#d4aa57"></div></div><label class="file-button wide">Upload token image<input type="file" id="token-image-input" accept="image/*"></label>`,`<button data-close-modal>Cancel</button><button class="primary" data-create-token>Add to scene</button>`);const root=$('#modal-root'),sel=$('#token-character');sel.onchange=()=>{const c=StudioData.character(sel.value);if(c){$('#token-name').value=c.name;$('#token-color').value=c.color||'#d4aa57'}};root.querySelector('[data-create-token]').onclick=async()=>{const c=StudioData.character(sel.value),file=$('#token-image-input').files[0],g=s.gridSize||70,x=pos?.x??g*2.5,y=pos?.y??g*2.5,token={id:uid(),characterId:c?.id||'',name:$('#token-name').value.trim()||c?.name||'Token',x,y,size:+$('#token-size').value||1,color:$('#token-color').value,imageDataUrl:file?await StudioData.fileToDataUrl(file):(c?.tokenDataUrl||c?.portraitDataUrl||''),hidden:false,bars:{hp:c?.hp??0,maxHp:c?.maxHp??0}};s.tokens.push(token);v.selectedTokenId=token.id;StudioData.save(true);closeModal();Workspace.render()};},
  editToken(id){const s=StudioData.scene(),t=s.tokens.find(x=>x.id===id);if(!t)return;modal('Edit token',`<div class="field"><label>Name</label><input id="edit-token-name" value="${esc(t.name)}"></div><div class="split"><div class="field"><label>Size</label><input id="edit-token-size" type="number" min="0.25" max="6" step="0.25" value="${t.size||1}"></div><div class="field"><label>Color</label><input id="edit-token-color" type="color" value="${esc(t.color||'#d4aa57')}"></div></div><label class="list-row"><input id="edit-token-hidden" type="checkbox" ${t.hidden?'checked':''}> Hidden from players</label><label class="file-button wide">Replace token image<input type="file" id="edit-token-image" accept="image/*"></label>`,`<button class="danger" data-delete-token>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-token>Save</button>`);const root=$('#modal-root');root.querySelector('[data-save-token]').onclick=async()=>{t.name=$('#edit-token-name').value.trim()||'Token';t.size=+$('#edit-token-size').value||1;t.color=$('#edit-token-color').value;t.hidden=$('#edit-token-hidden').checked;const file=$('#edit-token-image').files[0];if(file)t.imageDataUrl=await StudioData.fileToDataUrl(file);StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-token]').onclick=()=>{s.tokens=s.tokens.filter(x=>x.id!==id);StudioData.vtt().selectedTokenId='';StudioData.save(true);closeModal();Workspace.render()}},
  addInitiative(){const v=StudioData.vtt(),options=[...v.characters.map(c=>({name:c.name,color:c.color,bonus:c.initiativeBonus||0,characterId:c.id})),...StudioData.scene().tokens.map(t=>({name:t.name,color:t.color,bonus:0,tokenId:t.id}))];modal('Add initiative combatant',`<div class="field"><label>Combatant</label><select id="initiative-source">${options.map((o,i)=>`<option value="${i}">${esc(o.name)}</option>`).join('')}<option value="custom">Custom</option></select></div><div class="split"><div class="field"><label>Name</label><input id="initiative-name" value="${esc(options[0]?.name||'Combatant')}"></div><div class="field"><label>Initiative</label><input id="initiative-score" type="number" value="0"></div></div>`,`<button data-close-modal>Cancel</button><button data-roll-initiative>Roll d20</button><button class="primary" data-save-initiative>Add</button>`);const root=$('#modal-root'),source=$('#initiative-source');source.onchange=()=>{const o=options[+source.value];if(o)$('#initiative-name').value=o.name};root.querySelector('[data-roll-initiative]').onclick=()=>{const o=options[+source.value];$('#initiative-score').value=Math.floor(Math.random()*20)+1+(o?.bonus||0)};root.querySelector('[data-save-initiative]').onclick=()=>{const o=options[+source.value]||{};v.initiative.push({id:uid(),name:$('#initiative-name').value.trim()||'Combatant',score:+$('#initiative-score').value||0,color:o.color||'#d4aa57',characterId:o.characterId||'',tokenId:o.tokenId||''});v.initiative.sort((a,b)=>b.score-a.score);StudioData.save(true);closeModal();Workspace.render()}},
  nextTurn(delta){const v=StudioData.vtt();if(!v.initiative.length)return;const prev=v.turnIndex;v.turnIndex=(v.turnIndex+delta+v.initiative.length)%v.initiative.length;if(delta>0&&v.turnIndex<=prev)v.round++;if(delta<0&&v.turnIndex>=prev)v.round=Math.max(1,v.round-1);StudioData.save();Workspace.render()},
  roll(expression){expression=String(expression||'1d20').trim().toLowerCase().replace(/\s+/g,'');const m=expression.match(/^(\d{1,3})d(\d{1,4})([+-]\d+)?$/);if(!m)return toast('Use a dice expression like 1d20, 2d6+3, or 1d100-10.','error');const count=Math.min(100,+m[1]),sides=Math.max(2,+m[2]),mod=+(m[3]||0),rolls=Array.from({length:count},()=>crypto.getRandomValues(new Uint32Array(1))[0]%sides+1),total=rolls.reduce((a,b)=>a+b,0)+mod,detail=`[${rolls.join(', ')}]${mod?` ${mod>0?'+':'−'} ${Math.abs(mod)}`:''}`;StudioData.vtt().diceLog.unshift({id:uid(),expression,total,detail,user:State.user?.username||'Local player',at:new Date().toISOString()});StudioData.vtt().diceLog=StudioData.vtt().diceLog.slice(0,200);StudioData.save(true);Workspace.render()},
  editCharacter(id=null){const v=StudioData.vtt(),c=v.characters.find(x=>x.id===id),stats=c?.stats||{Strength:10,Dexterity:10,Constitution:10,Intelligence:10,Wisdom:10,Charisma:10};modal(c?'Edit character':'New character',`<div class="character-editor"><div class="split"><div class="field"><label>Name</label><input id="char-name" value="${esc(c?.name||'')}"></div><div class="field"><label>Player / controller</label><input id="char-player" value="${esc(c?.player||'')}"></div></div><div class="split"><div class="field"><label>System</label><input id="char-system" value="${esc(c?.system||'System Neutral')}"></div><div class="field"><label>Color</label><input id="char-color" type="color" value="${esc(c?.color||'#d4aa57')}"></div></div><div class="character-stat-editor">${Object.entries(stats).map(([k,val])=>`<label>${esc(k)}<input type="number" data-char-stat="${esc(k)}" value="${Number(val)||0}"><button type="button" data-reroll-stat="${esc(k)}">↻</button></label>`).join('')}</div><div class="split thirds"><div class="field"><label>HP</label><input id="char-hp" type="number" value="${c?.hp??10}"></div><div class="field"><label>Max HP</label><input id="char-max-hp" type="number" value="${c?.maxHp??10}"></div><div class="field"><label>AC / Defense</label><input id="char-ac" type="number" value="${c?.ac??10}"></div></div><div class="split"><div class="field"><label>Speed</label><input id="char-speed" value="${esc(c?.speed||'30 ft')}"></div><div class="field"><label>Initiative bonus</label><input id="char-init" type="number" value="${c?.initiativeBonus??0}"></div></div><div class="split"><label class="file-button wide">Portrait<input id="char-portrait" type="file" accept="image/*"></label><label class="file-button wide">Token<input id="char-token" type="file" accept="image/*"></label></div><div class="field"><label>Notes</label><textarea id="char-notes" rows="5">${esc(c?.notes||'')}</textarea></div><div class="field"><label>Complete system sheet JSON</label><textarea id="char-json" rows="7">${esc(JSON.stringify(c?.sheetJson||{},null,2))}</textarea></div></div>`,`<button class="danger" data-delete-character ${c?'':'disabled'}>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-character>Save</button>`,'wide');const root=$('#modal-root');root.querySelectorAll('[data-reroll-stat]').forEach(b=>b.onclick=()=>{const input=root.querySelector(`[data-char-stat="${CSS.escape(b.dataset.rerollStat)}"]`);input.value=Array.from({length:4},()=>Math.floor(Math.random()*6)+1).sort((a,b)=>a-b).slice(1).reduce((a,b)=>a+b,0)});root.querySelector('[data-save-character]').onclick=async()=>{let sheetJson={};try{sheetJson=JSON.parse($('#char-json').value||'{}')}catch{return toast('Character sheet JSON is not valid.','error')}const next={id:c?.id||uid(),name:$('#char-name').value.trim()||'Unnamed Character',player:$('#char-player').value,system:$('#char-system').value,color:$('#char-color').value,hp:+$('#char-hp').value||0,maxHp:+$('#char-max-hp').value||0,ac:+$('#char-ac').value||0,speed:$('#char-speed').value,initiativeBonus:+$('#char-init').value||0,stats:Object.fromEntries([...root.querySelectorAll('[data-char-stat]')].map(i=>[i.dataset.charStat,+i.value||0])),notes:$('#char-notes').value,sheetJson,portraitDataUrl:c?.portraitDataUrl||'',tokenDataUrl:c?.tokenDataUrl||'',createdAt:c?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};const portrait=$('#char-portrait').files[0],token=$('#char-token').files[0];if(portrait)next.portraitDataUrl=await StudioData.fileToDataUrl(portrait);if(token)next.tokenDataUrl=await StudioData.fileToDataUrl(token);if(c)Object.assign(c,next);else v.characters.push(next);StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-character]')?.addEventListener('click',()=>{if(!confirm(`Delete ${c.name}?`))return;v.characters=v.characters.filter(x=>x.id!==c.id);for(const s of v.scenes)s.tokens=s.tokens.map(t=>t.characterId===c.id?{...t,characterId:''}:t);StudioData.save(true);closeModal();Workspace.render()})},
  characterToScene(id){const c=StudioData.character(id),s=StudioData.scene();if(!c||!s)return;const g=s.gridSize||70;s.tokens.push({id:uid(),characterId:c.id,name:c.name,x:g*2.5,y:g*2.5,size:1,color:c.color||'#d4aa57',imageDataUrl:c.tokenDataUrl||c.portraitDataUrl||'',hidden:false,bars:{hp:c.hp,maxHp:c.maxHp}});StudioData.save(true);toast(`${c.name} added to ${s.name}.`,'success')},
  editHandout(id=null){const v=StudioData.vtt(),h=v.handouts.find(x=>x.id===id);modal(h?'Edit handout':'New handout',`<div class="field"><label>Title</label><input id="handout-title" value="${esc(h?.title||'')}"></div><div class="split"><div class="field"><label>Visibility</label><select id="handout-visibility">${['runner','party','public'].map(x=>`<option ${h?.visibility===x?'selected':''}>${x}</option>`).join('')}</select></div><label class="file-button wide">Attach image<input id="handout-image" type="file" accept="image/*"></label></div><div class="field"><label>Summary</label><input id="handout-summary" value="${esc(h?.summary||'')}"></div><div class="field"><label>Content</label><textarea id="handout-content" rows="12">${esc(h?.content||'')}</textarea></div>`,`<button class="danger" data-delete-handout ${h?'':'disabled'}>Delete</button><button data-close-modal>Cancel</button><button class="primary" data-save-handout>Save</button>`,'wide');const root=$('#modal-root');root.querySelector('[data-save-handout]').onclick=async()=>{const next={id:h?.id||uid(),title:$('#handout-title').value.trim()||'Untitled Handout',visibility:$('#handout-visibility').value,summary:$('#handout-summary').value,content:$('#handout-content').value,imageDataUrl:h?.imageDataUrl||'',updatedAt:new Date().toISOString()};const file=$('#handout-image').files[0];if(file)next.imageDataUrl=await StudioData.fileToDataUrl(file);if(h)Object.assign(h,next);else v.handouts.push(next);StudioData.save(true);closeModal();Workspace.render()};root.querySelector('[data-delete-handout]')?.addEventListener('click',()=>{v.handouts=v.handouts.filter(x=>x.id!==h.id);StudioData.save(true);closeModal();Workspace.render()})}
};

